// Hand-authored novel command support: Excel report engine. Not generated;
// safe across regeneration (no "Generated by" header).
package cli

import (
	"context"
	"fmt"
	"time"

	"github.com/mvanhorn/printing-press-library/library/other/scientific-consensus/internal/scengine"
	"github.com/xuri/excelize/v2"
)

// CitationSummary is one flattened, spreadsheet-ready row of the works report:
// the normalized scWork fields plus the scengine design/stance classification.
type CitationSummary struct {
	Title            string          `json:"title"`
	FirstAuthor      string          `json:"first_author,omitempty"`
	Year             int             `json:"year,omitempty"`
	DOI              string          `json:"doi,omitempty"`
	PMID             string          `json:"pmid,omitempty"`
	Venue            string          `json:"venue,omitempty"`
	Type             string          `json:"type,omitempty"`
	Design           scengine.Design `json:"design"`
	Stance           scengine.Stance `json:"stance"`
	StanceConfidence float64         `json:"stance_confidence"`
	CitedBy          int             `json:"cited_by_count"`
	OpenAccess       bool            `json:"open_access"`
}

// reportData is everything the Excel writer needs: the per-work rows plus the
// aggregate stats shown on the Summary sheet.
type reportData struct {
	Query        string            `json:"query"`
	Filter       string            `json:"filter,omitempty"`
	Claim        string            `json:"claim"`
	TotalMatches int               `json:"total_matches"`
	Analyzed     int               `json:"analyzed"`
	Supporting   int               `json:"supporting"`
	Refuting     int               `json:"refuting"`
	Mixed        int               `json:"mixed"`
	Inconclusive int               `json:"inconclusive"`
	ApexDesign   scengine.Design   `json:"apex_design"`
	StanceMethod string            `json:"stance_method"`
	GeneratedAt  time.Time         `json:"generated_at"`
	Rows         []CitationSummary `json:"rows"`
}

// buildReportData fetches works for the query, classifies each one, and
// aggregates the stance/design stats. claim defaults to the query when empty.
func buildReportData(ctx context.Context, c apiGetter, query, filter, claim string, limit int) (*reportData, error) {
	if claim == "" {
		claim = query
	}
	works, total, err := fetchWorks(ctx, c, query, filter, "", limit)
	if err != nil {
		return nil, err
	}
	_, stances := scoreWorks(ctx, works, claim)

	data := &reportData{
		Query:        query,
		Filter:       filter,
		Claim:        claim,
		TotalMatches: total,
		Analyzed:     len(works),
		GeneratedAt:  time.Now().UTC(),
		Rows:         make([]CitationSummary, 0, len(stances)),
	}
	classifications := make([]scengine.Classification, 0, len(stances))
	for _, st := range stances {
		switch st.Stance {
		case scengine.StanceSupporting:
			data.Supporting++
		case scengine.StanceRefuting:
			data.Refuting++
		case scengine.StanceMixed:
			data.Mixed++
		default:
			data.Inconclusive++
		}
		if data.StanceMethod == "" && st.StanceMethod != "" {
			data.StanceMethod = st.StanceMethod
		}
		classifications = append(classifications, scengine.Classification{Design: st.Design, Method: st.Method})
		data.Rows = append(data.Rows, CitationSummary{
			Title:            st.Work.Title,
			FirstAuthor:      st.Work.FirstAuthor,
			Year:             st.Work.Year,
			DOI:              st.Work.DOI,
			PMID:             st.Work.PMID,
			Venue:            st.Work.Venue,
			Type:             st.Work.Type,
			Design:           st.Design,
			Stance:           st.Stance,
			StanceConfidence: st.Confidence,
			CitedBy:          st.Work.CitedBy,
			OpenAccess:       st.Work.IsOA,
		})
	}
	if data.StanceMethod == "" {
		data.StanceMethod = "heuristic"
	}
	if len(classifications) > 0 {
		data.ApexDesign = scengine.ApexDesign(classifications)
	}
	return data, nil
}

// worksHeader is the fixed column order of the Works sheet.
var worksHeader = []any{
	"Title", "First Author", "Year", "DOI", "PMID", "Journal/Venue",
	"Type", "Design", "Stance", "Stance Confidence", "Cited By", "Open Access",
}

// writeReportXLSX renders data into a two-sheet workbook (Works + Summary) at
// path. An empty result set still produces a valid file with headers and the
// Summary sheet so downstream tooling never sees a missing artifact.
func writeReportXLSX(path string, data *reportData) (err error) {
	f := excelize.NewFile()
	defer func() {
		if cerr := f.Close(); cerr != nil && err == nil {
			err = cerr
		}
	}()

	const worksSheet = "Works"
	const summarySheet = "Summary"
	if err = f.SetSheetName("Sheet1", worksSheet); err != nil {
		return fmt.Errorf("naming Works sheet: %w", err)
	}
	if _, err = f.NewSheet(summarySheet); err != nil {
		return fmt.Errorf("creating Summary sheet: %w", err)
	}

	headerStyle, err := f.NewStyle(&excelize.Style{Font: &excelize.Font{Bold: true}})
	if err != nil {
		return fmt.Errorf("creating header style: %w", err)
	}

	// Works sheet: bold header row, one row per work.
	if err = f.SetSheetRow(worksSheet, "A1", &worksHeader); err != nil {
		return fmt.Errorf("writing Works header: %w", err)
	}
	if err = f.SetCellStyle(worksSheet, "A1", "L1", headerStyle); err != nil {
		return fmt.Errorf("styling Works header: %w", err)
	}
	for i, r := range data.Rows {
		cell, cerr := excelize.CoordinatesToCellName(1, i+2)
		if cerr != nil {
			return fmt.Errorf("computing row coordinate: %w", cerr)
		}
		row := []any{
			r.Title, r.FirstAuthor, r.Year, r.DOI, r.PMID, r.Venue,
			r.Type, string(r.Design), string(r.Stance), r.StanceConfidence, r.CitedBy, r.OpenAccess,
		}
		if err = f.SetSheetRow(worksSheet, cell, &row); err != nil {
			return fmt.Errorf("writing Works row %d: %w", i+1, err)
		}
	}
	for col, width := range map[string]float64{"A": 60, "B": 22, "D": 28, "E": 12, "F": 32, "G": 14, "H": 26, "I": 14, "J": 16, "K": 10, "L": 12} {
		if err = f.SetColWidth(worksSheet, col, col, width); err != nil {
			return fmt.Errorf("sizing Works column %s: %w", col, err)
		}
	}

	// Summary sheet: key/value metadata rows.
	summaryRows := [][]any{
		{"Query", data.Query},
		{"Filter", data.Filter},
		{"Claim", data.Claim},
		{"Total matches (OpenAlex)", data.TotalMatches},
		{"Works analyzed", data.Analyzed},
		{"Supporting", data.Supporting},
		{"Refuting", data.Refuting},
		{"Mixed", data.Mixed},
		{"Inconclusive", data.Inconclusive},
		{"Strongest design present", string(data.ApexDesign)},
		{"Stance method", data.StanceMethod},
		{"Generated at (UTC)", data.GeneratedAt.Format(time.RFC3339)},
		{"CLI version", version},
	}
	for i, kv := range summaryRows {
		cell, cerr := excelize.CoordinatesToCellName(1, i+1)
		if cerr != nil {
			return fmt.Errorf("computing summary coordinate: %w", cerr)
		}
		if err = f.SetSheetRow(summarySheet, cell, &kv); err != nil {
			return fmt.Errorf("writing Summary row %d: %w", i+1, err)
		}
	}
	lastLabel, cerr := excelize.CoordinatesToCellName(1, len(summaryRows))
	if cerr != nil {
		return fmt.Errorf("computing summary style range: %w", cerr)
	}
	if err = f.SetCellStyle(summarySheet, "A1", lastLabel, headerStyle); err != nil {
		return fmt.Errorf("styling Summary labels: %w", err)
	}
	if err = f.SetColWidth(summarySheet, "A", "A", 28); err != nil {
		return fmt.Errorf("sizing Summary column: %w", err)
	}
	if err = f.SetColWidth(summarySheet, "B", "B", 60); err != nil {
		return fmt.Errorf("sizing Summary column: %w", err)
	}

	if err = f.SaveAs(path); err != nil {
		return fmt.Errorf("saving %s: %w", path, err)
	}
	return nil
}
